#pragma once
// ---------------------------------------------------------------------------
// A compact block produced by litecoind itself -- the anchor for the BIP 152
// short-id KAT (our SipHash keys and short ids must reproduce litecoind's).
//
// Produced 2026-10-24 with /LitecoinCore:0.21.5.6/ on a throwaway regtest node (fresh
// datadir, private ports 19883/19884, MWEB never activated, stopped and
// removed afterwards; the shared regtest rigs were not touched):
//
//   litecoind -datadir=$D -vbparams=mweb:9223372036854775806:9223372036854775807
//     (litecoin.conf: regtest=1 server=1 [regtest] rpcport=19883 port=19884
//      bind=127.0.0.1 listen=1 fallbackfee=0.0002 dnsseed=0 connect=0)
//   litecoin-cli createwallet vec
//   A=$(litecoin-cli getnewaddress "" bech32); litecoin-cli generatetoaddress 110 $A
//   six sendtoaddress to fresh bech32 / legacy / p2sh-segwit addresses
//     (1.5, 2.25, 0.75, 3.1, 0.42, 5.0 LTC; every one spends a segwit coinbase,
//      so every non-coinbase tx has a witness and wtxid != txid)
//   litecoin-cli generatetoaddress 1 $A                 -> the block below
//   litecoin-cli getblockheader <hash> false / getblock <hash> 0 / getblock <hash> 2
// then a stdlib python P2P client (version 70017, services NETWORK|WITNESS|
// MWEB, verack) sent, on two connections:
//   kCmpctV2Hex:  sendcmpct(false, 2)                    then getdata(MSG_CMPCT_BLOCK=4, hash)
//   kCmpctV3Hex:  sendcmpct(false, 3), sendcmpct(false, 2) then getdata(4, hash)
// and saved each "cmpctblock" payload verbatim. litecoind advertised NODE_MWEB
// (services 0x1800449) and locked v3 on the second connection, so that payload
// carries the MWEB field, null (presence 0), because MWEB is not active.
// Regtest litecoind cannot mine an MWEB block (the 0.21.5.6 miner emits an
// invalid first HogEx), so there is no HogEx / mw::Block in this vector; the
// HogEx side is pinned by the mainnet vector (ltc_mweb_cmpct_fixtures.hpp).
//
// Do not hand-edit.
// ---------------------------------------------------------------------------

